import{z as A,x as B,o as E,c as d,q as o,j as i,D as l,d as r,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"blk-mq","description":"","frontmatter":{"title":"blk-mq","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blk-mq.md","filePath":"cs/blk-mq.md","lastUpdated":1791063341000}'),m={name:"cs/blk-mq.md"};function p(b,a,u,C,q,k){const t=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="blk-mq" tabindex="-1">blk-mq <a class="header-anchor" href="#blk-mq" aria-label="Permalink to &quot;blk-mq&quot;">​</a></h1><div class="epigraph"><p>多队列块层让每个 CPU、每个硬件队列各有提交路径，避免一把大锁串行化所有请求。</p><footer>—— 据 Axboe 对 Linux 多队列块层的设计；Silberschatz 对 I/O 子系统的整理</footer></div><p><a href="/cs/disk-sched">上一课</a>在单队列上讲 SCAN/LOOK。NVMe 与多核上，全局电梯自己成为瓶颈：锁与缓存行争用超过寻道。<a href="/cs/writeback">writeback</a> 会从各 CPU 同时提交。缺口是 <strong>blk-mq</strong>：软件队列对硬件队列，调度下沉到每队列或设备侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典 request_queue 一把锁保护电梯。SSD 没有磁头，FCFS 或简单合并更合适，但锁仍序列化。缺口：每 CPU 一个 software staging queue，映射到设备的多条 hardware queue；完成中断可绑在对应核。合并与超时仍在，只是范围变成每队列。本课不把 mq-deadline/kyber/none 的参数表背完。</p><p><span class="marginnote">none 调度器几乎只做合并与派发，适合 NVMe。机械盘仍可用单硬件队列加上 deadline，教学上承认「电梯不是消失，是可选插件」。</span></p><p><span class="marginnote">术语翻译：软件队列是本 CPU 内存里的「待办筐」，硬件队列是设备真实拥有的提交通道；「门铃」（doorbell）就是往设备寄存器写一笔「筐里有货了」，设备自己去 DMA 取——CPU 从此不用轮询。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FS/VFS 提交的请求进入本 CPU 的软件队列，可选插入 I/O 调度器，再映射到硬件队列门铃。完成：IRQ → 下半部在对应核清请求、结束 bio。与 <a href="/cs/interrupt-bottom-half">中断下半部</a> 已有路径对接。不要在此重写 DMA；下一课 bio 才是请求的内存形状。</p>',9)),(E(),i(n,null,{default:l(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22%E6%AF%8F%20CPU%20%E8%BD%AF%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%20--%3E%20SCH%5B%22%E5%8F%AF%E9%80%89%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20SCH%20--%3E%20HW%5B%22%E7%A1%AC%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20HW%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E5%88%B0%E5%AF%B9%E5%BA%94%E6%A0%B8%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：旧块层像全城只开一个收银台，所有顾客抢同一把椅子还要经理盖章；blk-mq 像每个入口各配收银台。省下的不是「理货」（寻道早没有了），而是排到收银台之前的那段队伍——锁与缓存行争用。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"blk-mq 把块层从「一个电梯」改成「可扩展提交」：多道写回不再挤在同一把锁上。磁盘调度课的公平与饥饿问题仍可能在单队列插件里出现；多队列上公平变成每核/每 cgroup 的配额，隔离课再谈。本课只钉队列拓扑。",-1)),a[6]||(a[6]=e("p",null,"与网络栈的多队列网卡类似，但对象仍是块请求，不是帧。",-1)),a[7]||(a[7]=e("p",null,"新旧提交路径差在哪，可以并排看。",-1)),(E(),i(n,null,{default:l(()=>[s(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E5%8D%95%E9%98%9F%E5%88%97%EF%BC%9A%E4%B8%80%E6%8A%8A%E9%94%81%E4%BF%9D%E6%8A%A4%E7%94%B5%E6%A2%AF%22%5D%20--%3E%20OLDL%5B%2216%20%E6%A0%B8%E6%8C%A4%E5%90%8C%E4%B8%80%E6%9D%A1%E6%8F%90%E4%BA%A4%E8%B7%AF%E5%BE%84%22%5D%0A%20%20OLDL%20--%3E%20LOCK%5B%22%E9%94%81%E4%B8%8E%E7%BC%93%E5%AD%98%E8%A1%8C%E4%BA%89%E7%94%A8%E5%B0%81%E9%A1%B6%E5%90%9E%E5%90%90%22%5D%0A%20%20NEW%5B%22blk-mq%EF%BC%9A%E6%AF%8F%20CPU%20%E8%BD%AF%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%E5%A4%9A%E6%9D%A1%E7%A1%AC%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20MAP%20--%3E%20PAR%5B%22%E6%8F%90%E4%BA%A4%E8%B7%AF%E5%BE%84%E5%B9%B6%E8%A1%8C%EF%BC%8C%E9%94%81%E8%8C%83%E5%9B%B4%E7%BC%A9%E5%B0%8F%E5%88%B0%E6%AF%8F%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">常见误区：以为多队列是为了「排队更公平」或「排序更好」。它解决的是锁的串行化——吞吐瓶颈从磁盘移到块层后，唯一挡路的是那把全局锁。至于公平与饥饿，blk-mq 把它们拆成每核、每 cgroup 的配额问题，交给隔离机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 io_uring 与 blk-mq 的对接全文（后课 io_uring）。不保证所有设备暴露多硬件队列。下一课：一条请求如何描述「这些页、这些扇区」——bio。</p><p>后课默认：提交可并行进多队列。分散聚集的请求对象是 bio。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>blk-mq 用每 CPU/每硬件队列去掉全局电梯锁。</li><li>调度器变成可选插件；NVMe 常用 none。</li><li>请求的页与扇区描述是 bio 的缺口。</li><li>出处：Axboe, Linux blk-mq；Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',6))])}const h=A(m,[["render",p]]);export{D as __pageData,h as default};
